import{_ as e,c as t,a as d,o as c}from"./index-B3LiEHuY.js";const n={};function s(r,o){return c(),t("section",null,[...o[0]||(o[0]=[d(`<h2><span class="no">06</span>完整部署流程（从零开始）</h2><h3>第 0 步：准备环境（只做一次）</h3><ul><li>安装 <strong>Go 1.25+</strong>：https://go.dev/dl/（验证：<code>go version</code>）</li><li>安装 <strong>Node.js 18+</strong>：https://nodejs.org/（验证：<code>node --version</code>）</li><li>安装 <strong>Docker</strong>（推荐，用于跑 MySQL）：https://www.docker.com/products/docker-desktop</li></ul><h3>第 1 步：启动 MySQL</h3><p><strong>方式一：Docker（推荐）</strong>——在项目根目录执行：</p><pre><code>docker compose up -d</code></pre><p>会自动下载 MySQL 8 镜像并启动，账号密码见「数据库访问方法」。</p><p><strong>方式二：本地安装 MySQL 8</strong>——安装后手动建库并授权：</p><pre><code>CREATE DATABASE IF NOT EXISTS blog CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
CREATE USER IF NOT EXISTS &#39;blog&#39;@&#39;localhost&#39; IDENTIFIED BY &#39;blog123456&#39;;
GRANT ALL PRIVILEGES ON blog.* TO &#39;blog&#39;@&#39;localhost&#39;;
FLUSH PRIVILEGES;</code></pre><div class="box tip">后端启动时会<strong>自动建库建表</strong>，第 1 步只是保证「库存在、账号有权限」。</div><h3>第 2 步：安装前端依赖并构建</h3><pre><code><span class="comment"># 进入前端目录</span>
cd frontend
npm install
npm run build   <span class="comment"># 产物输出到 frontend/dist（后端会直接托管它）</span></code></pre><h3>第 3 步：启动后端</h3><pre><code><span class="comment"># 回到项目根目录，进入后端目录</span>
cd ../backend
go build -o blog-server.exe .    <span class="comment"># 编译（可跳过，直接用 go run）</span>
./blog-server.exe                 <span class="comment"># 或 go run .</span></code></pre><p>看到日志 <code>凛冬博客后端已启动: http://localhost:8080</code> 即成功。若连接 MySQL 报错，检查数据库是否已启动、账号密码是否匹配。</p><div class="box tip">国内网络下载 Go 依赖慢/失败时，先执行：<code>$env:GOPROXY=&quot;https://goproxy.cn,direct&quot;; go run .</code></div><h3>第 4 步：验证</h3><table><tr><th>地址</th><th>内容</th></tr><tr><td>http://localhost:8080</td><td>个人主页</td></tr><tr><td>http://localhost:8080/blog</td><td>博客列表</td></tr><tr><td>http://localhost:8080/admin/login</td><td>后台登录</td></tr></table><h3>开发模式（改代码热更新）</h3><p>开两个终端：终端 1 跑 <code>cd backend &amp;&amp; go run .</code>；终端 2 跑 <code>cd frontend &amp;&amp; npm run dev</code>，然后访问 <code>http://localhost:5173</code>。前端改动实时生效；后端改动需重启。Vite 会自动把 <code>/api</code>、<code>/uploads</code> 代理到 8080，所以前后端互通无跨域问题。</p><h3>部署到服务器（进阶）</h3><ol><li>服务器装好 Go/Node/MySQL（或 Docker）</li><li>按上面流程构建前端（<code>npm run build</code>）与后端（<code>go build</code>）</li><li>把 <code>frontend/dist</code>、后端可执行文件、<code>docs/</code> 传到服务器</li><li>设置环境变量（数据库地址、管理员密码等），启动后端进程（可用 systemd / supervisor 守护）</li><li>可选：用 Nginx 反向代理 80 端口到 8080，并配 HTTPS</li></ol>`,22)])])}const p=e(n,[["render",s]]);export{p as default};
